import { sql, type Kysely } from 'kysely';

// The tables of design §4.2 (FND-04). The conventions are recorded in design §14 under
// 工具與專案結構; in short:
//
// - Identifiers are uuid, generated by the database when an insert gives none. Identifiers
//   that come from outside (Google, LINE, WhatsApp, the app's device ID) and hashes are text.
// - Only `id`, `created_at` and `updated_at` have a default. No threshold or time constant
//   of design §9.2 appears here: those are configuration.
// - A closed set of values that code branches on has a CHECK. Classifications that are
//   expected to grow, and sets that no document enumerates yet, are plain text.
// - Every business table has `user_id`. Deleting a user deletes the user's rows, except
//   consent records (kept until ACC-06 decides) and the WhatsApp send log (kept, without the
//   user, for the budget count).
// - A reference to a source message becomes NULL when the message is deleted (ADR-0004).
//
// Not here on purpose: the keyword index on messages.text (AGT-04, after SPK-06), database
// roles and grants (DEC-09), the connector's connection lease (ADR-0025) and pg-boss's own
// tables (FND-06).
//
// A migration that has been applied anywhere is never edited; add a new one instead.

const statements = [
  // --- Identity and consent ---
  `CREATE TABLE users (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    google_sub text NOT NULL UNIQUE,
    email text NOT NULL,
    display_name text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
  )`,

  // Not user data. The address is stored in lower case so that a lookup is one comparison.
  `CREATE TABLE invites (
    email text PRIMARY KEY CHECK (email = lower(email)),
    created_at timestamptz NOT NULL DEFAULT now()
  )`,

  // Not user data.
  `CREATE TABLE consent_documents (
    type text NOT NULL,
    version text NOT NULL,
    title text NOT NULL,
    url text NOT NULL,
    published_at timestamptz NOT NULL,
    PRIMARY KEY (type, version)
  )`,

  // One row per act of consent (ADR-0022), so accepting a version again adds a row.
  // No ON DELETE on user_id: ADR-0022 leaves open what happens to consent records when the
  // account is deleted, so the deletion must handle them explicitly (ACC-06).
  `CREATE TABLE consent_records (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users,
    type text NOT NULL,
    version text NOT NULL,
    accepted_at timestamptz NOT NULL,
    FOREIGN KEY (type, version) REFERENCES consent_documents
  )`,
  `CREATE INDEX consent_records_user_id_idx ON consent_records (user_id)`,
  `CREATE INDEX consent_records_type_version_idx ON consent_records (type, version)`,

  // device_id is the identifier the app generated; a token can exist before the device has
  // registered for push, so it does not reference devices.
  `CREATE TABLE refresh_tokens (
    token_hash text PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    device_id text NOT NULL,
    family_id uuid NOT NULL,
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz
  )`,
  `CREATE INDEX refresh_tokens_user_id_idx ON refresh_tokens (user_id)`,
  `CREATE INDEX refresh_tokens_family_id_idx ON refresh_tokens (family_id)`,

  `CREATE TABLE devices (
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    device_id text NOT NULL,
    platform text NOT NULL CHECK (platform IN ('ios', 'android')),
    fcm_token text NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, device_id)
  )`,

  `CREATE TABLE user_settings (
    user_id uuid PRIMARY KEY REFERENCES users ON DELETE CASCADE,
    retention_days integer NOT NULL CHECK (retention_days > 0),
    time_zone text NOT NULL,
    quiet_hours_start time NOT NULL,
    quiet_hours_end time NOT NULL,
    notify_task_reminders boolean NOT NULL,
    notify_scam_alerts boolean NOT NULL,
    notify_connection_status boolean NOT NULL,
    notify_agent_results boolean NOT NULL
  )`,

  // --- LINE connection and messages ---

  // credentials is stored plain, by decision (ADR-0005). Do not add encryption here.
  `CREATE TABLE line_connections (
    user_id uuid PRIMARY KEY REFERENCES users ON DELETE CASCADE,
    status text NOT NULL
      CHECK (status IN ('not_linked', 'connected', 'reconnecting', 'expired')),
    credentials jsonb,
    linked_at timestamptz,
    last_event_at timestamptz
  )`,

  `CREATE TABLE line_link_sessions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    status text NOT NULL CHECK (status IN (
      'pending', 'awaiting_scan', 'awaiting_verification',
      'completed', 'failed', 'expired', 'cancelled'
    )),
    qr_payload text,
    verification_code text,
    failure_reason text,
    expires_at timestamptz NOT NULL
  )`,
  `CREATE INDEX line_link_sessions_user_id_idx ON line_link_sessions (user_id)`,

  `CREATE TABLE conversations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    platform text NOT NULL CHECK (platform IN ('line')),
    external_id text NOT NULL,
    type text NOT NULL CHECK (type IN ('direct', 'group', 'official_account')),
    name text NOT NULL,
    ingestion_override text CHECK (ingestion_override IN ('include', 'exclude')),
    first_seen_at timestamptz NOT NULL,
    last_message_at timestamptz,
    UNIQUE (user_id, platform, external_id)
  )`,

  // text is stored plain, by decision (ADR-0005), and is NULL for a message that is not
  // text. The unique constraint makes a message that is received twice a no-op.
  `CREATE TABLE messages (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    conversation_id uuid NOT NULL REFERENCES conversations ON DELETE CASCADE,
    external_id text NOT NULL,
    sender_external_id text NOT NULL,
    sender_name text NOT NULL,
    direction text NOT NULL CHECK (direction IN ('incoming', 'outgoing')),
    content_type text NOT NULL,
    text text,
    sent_at timestamptz NOT NULL,
    received_at timestamptz NOT NULL,
    UNIQUE (conversation_id, external_id)
  )`,
  `CREATE INDEX messages_user_id_idx ON messages (user_id)`,
  // The Chinese keyword index on messages.text goes here, in a later migration: AGT-04
  // creates it once SPK-06 has chosen between pg_bigm and pg_trgm (ADR-0015).

  `CREATE TABLE pipeline_windows (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    conversation_id uuid NOT NULL REFERENCES conversations ON DELETE CASCADE,
    status text NOT NULL,
    first_message_at timestamptz NOT NULL,
    last_message_at timestamptz NOT NULL,
    message_count integer NOT NULL CHECK (message_count >= 0),
    processed_at timestamptz
  )`,
  `CREATE INDEX pipeline_windows_user_id_idx ON pipeline_windows (user_id)`,
  `CREATE INDEX pipeline_windows_conversation_id_idx ON pipeline_windows (conversation_id)`,
  // A conversation has at most one unprocessed window at a time (ADR-0007).
  `CREATE UNIQUE INDEX pipeline_windows_one_unprocessed_per_conversation
    ON pipeline_windows (conversation_id) WHERE processed_at IS NULL`,

  // --- Travel (before tasks, which refer to trips) ---
  `CREATE TABLE trips (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    name text NOT NULL,
    destination text NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    time_zone text NOT NULL,
    status text NOT NULL CHECK (status IN ('planning', 'confirmed', 'completed', 'cancelled')),
    notes text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (end_date >= start_date)
  )`,
  `CREATE INDEX trips_user_id_idx ON trips (user_id)`,

  `CREATE TABLE itinerary_items (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    trip_id uuid NOT NULL REFERENCES trips ON DELETE CASCADE,
    date date NOT NULL,
    start_time time NOT NULL,
    end_time time,
    type text NOT NULL,
    title text NOT NULL,
    notes text,
    place jsonb,
    transport jsonb,
    position integer NOT NULL CHECK (position >= 0)
  )`,
  `CREATE INDEX itinerary_items_user_id_idx ON itinerary_items (user_id)`,
  `CREATE INDEX itinerary_items_trip_id_idx ON itinerary_items (trip_id)`,

  // item_id is not a foreign key: the record of an item's deletion has to outlive the item
  // and still say which item it was.
  `CREATE TABLE trip_changes (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    trip_id uuid NOT NULL REFERENCES trips ON DELETE CASCADE,
    item_id uuid,
    actor text NOT NULL CHECK (actor IN ('pipeline', 'agent', 'user')),
    before jsonb,
    after jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    reverted_at timestamptz
  )`,
  `CREATE INDEX trip_changes_user_id_idx ON trip_changes (user_id)`,
  `CREATE INDEX trip_changes_trip_id_idx ON trip_changes (trip_id)`,

  // --- Tasks and reminders ---

  // A task holds AI-summarised fields only, never message text (ADR-0004).
  `CREATE TABLE tasks (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    title text NOT NULL,
    date date NOT NULL,
    time time,
    all_day boolean NOT NULL,
    category text NOT NULL,
    status text NOT NULL CHECK (status IN ('active', 'completed', 'cancelled')),
    source text NOT NULL CHECK (source IN ('pipeline', 'user', 'agent')),
    confidence double precision CHECK (confidence BETWEEN 0 AND 1),
    user_modified boolean NOT NULL,
    source_conversation_id uuid REFERENCES conversations ON DELETE SET NULL,
    source_message_id uuid REFERENCES messages ON DELETE SET NULL,
    trip_id uuid REFERENCES trips ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE INDEX tasks_user_id_idx ON tasks (user_id)`,
  `CREATE INDEX tasks_source_conversation_id_idx ON tasks (source_conversation_id)`,
  // The daily purge deletes messages in bulk; without this index every delete scans tasks.
  `CREATE INDEX tasks_source_message_id_idx ON tasks (source_message_id)`,
  `CREATE INDEX tasks_trip_id_idx ON tasks (trip_id)`,

  // proposed holds task fields only, never message text (ADR-0004).
  `CREATE TABLE task_proposals (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    kind text NOT NULL CHECK (kind IN ('create', 'update', 'cancel')),
    task_id uuid REFERENCES tasks ON DELETE CASCADE,
    proposed jsonb NOT NULL,
    confidence double precision NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    status text NOT NULL CHECK (status IN ('pending', 'accepted', 'rejected', 'superseded')),
    source_conversation_id uuid REFERENCES conversations ON DELETE SET NULL,
    source_message_id uuid REFERENCES messages ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT task_proposals_target_check CHECK (kind = 'create' OR task_id IS NOT NULL)
  )`,
  `CREATE INDEX task_proposals_user_id_idx ON task_proposals (user_id)`,
  `CREATE INDEX task_proposals_task_id_idx ON task_proposals (task_id)`,
  `CREATE INDEX task_proposals_source_conversation_id_idx
    ON task_proposals (source_conversation_id)`,
  `CREATE INDEX task_proposals_source_message_id_idx ON task_proposals (source_message_id)`,

  `CREATE TABLE task_changes (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    task_id uuid NOT NULL REFERENCES tasks ON DELETE CASCADE,
    actor text NOT NULL CHECK (actor IN ('pipeline', 'agent', 'user')),
    before jsonb,
    after jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    reverted_at timestamptz
  )`,
  `CREATE INDEX task_changes_user_id_idx ON task_changes (user_id)`,
  `CREATE INDEX task_changes_task_id_idx ON task_changes (task_id)`,

  `CREATE TABLE reminders (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    task_id uuid NOT NULL REFERENCES tasks ON DELETE CASCADE,
    remind_at timestamptz NOT NULL,
    status text NOT NULL CHECK (status IN ('scheduled', 'sent', 'cancelled')),
    origin text NOT NULL CHECK (origin IN ('ai', 'user')),
    user_modified boolean NOT NULL
  )`,
  `CREATE INDEX reminders_user_id_idx ON reminders (user_id)`,
  `CREATE INDEX reminders_task_id_idx ON reminders (task_id)`,

  // --- Suspicious messages ---

  // reason is one sentence written by the model and never quotes the message (ADR-0009).
  // No ON DELETE on conversation_id: an alert always has a conversation, so the work item
  // that deletes conversations decides what happens to their alerts.
  `CREATE TABLE scam_alerts (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    conversation_id uuid NOT NULL REFERENCES conversations,
    category text NOT NULL,
    confidence double precision NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    level text NOT NULL CHECK (level IN ('high', 'medium')),
    reason text NOT NULL,
    status text NOT NULL CHECK (status IN ('open', 'dismissed')),
    feedback text CHECK (feedback IN ('not_scam', 'confirmed_scam')),
    source_message_id uuid REFERENCES messages ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE INDEX scam_alerts_user_id_idx ON scam_alerts (user_id)`,
  `CREATE INDEX scam_alerts_conversation_id_idx ON scam_alerts (conversation_id)`,
  `CREATE INDEX scam_alerts_source_message_id_idx ON scam_alerts (source_message_id)`,

  // --- Agent ---
  `CREATE TABLE memory_entries (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    content text NOT NULL,
    source_channel text NOT NULL CHECK (source_channel IN ('app', 'line_oa', 'whatsapp_oa')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE INDEX memory_entries_user_id_idx ON memory_entries (user_id)`,

  `CREATE TABLE agent_conversations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    channel text NOT NULL CHECK (channel IN ('app', 'line_oa', 'whatsapp_oa')),
    title text,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_message_at timestamptz
  )`,
  `CREATE INDEX agent_conversations_user_id_idx ON agent_conversations (user_id)`,

  `CREATE TABLE agent_messages (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    conversation_id uuid NOT NULL REFERENCES agent_conversations ON DELETE CASCADE,
    role text NOT NULL CHECK (role IN ('user', 'assistant')),
    channel text NOT NULL CHECK (channel IN ('app', 'line_oa', 'whatsapp_oa')),
    content text NOT NULL,
    status text NOT NULL CHECK (status IN ('completed', 'in_progress', 'failed')),
    created_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE INDEX agent_messages_user_id_idx ON agent_messages (user_id)`,
  `CREATE INDEX agent_messages_conversation_id_idx ON agent_messages (conversation_id)`,

  `CREATE TABLE agent_runs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    conversation_id uuid NOT NULL REFERENCES agent_conversations ON DELETE CASCADE,
    status text NOT NULL,
    started_at timestamptz NOT NULL,
    finished_at timestamptz,
    delivery text
  )`,
  `CREATE INDEX agent_runs_user_id_idx ON agent_runs (user_id)`,
  `CREATE INDEX agent_runs_conversation_id_idx ON agent_runs (conversation_id)`,

  // --- Official accounts ---

  // One binding per user and platform, and one user per account on the platform.
  `CREATE TABLE oa_bindings (
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    platform text NOT NULL CHECK (platform IN ('line', 'whatsapp')),
    external_user_id text NOT NULL,
    bound_at timestamptz NOT NULL,
    PRIMARY KEY (user_id, platform),
    UNIQUE (platform, external_user_id)
  )`,

  `CREATE TABLE oa_binding_codes (
    code_hash text PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    platform text NOT NULL CHECK (platform IN ('line', 'whatsapp')),
    expires_at timestamptz NOT NULL,
    used_at timestamptz
  )`,
  `CREATE INDEX oa_binding_codes_user_id_idx ON oa_binding_codes (user_id)`,

  // user_id is NULL for a reply to a sender who is not bound, which also counts towards the
  // budget (ADR-0024). It becomes NULL when the user is deleted, so the count stays right.
  `CREATE TABLE whatsapp_outbound_log (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid REFERENCES users ON DELETE SET NULL,
    kind text NOT NULL,
    sent_at timestamptz NOT NULL
  )`,
  `CREATE INDEX whatsapp_outbound_log_user_id_idx ON whatsapp_outbound_log (user_id)`,

  // --- Notifications ---

  // title is a summary only (ADR-0018). ref_type and ref_id name a resource of any kind, so
  // ref_id is not a foreign key.
  `CREATE TABLE notifications (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,
    type text NOT NULL,
    title text NOT NULL,
    ref_type text,
    ref_id uuid,
    read_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE INDEX notifications_user_id_idx ON notifications (user_id)`,
];

export async function up(db: Kysely<unknown>): Promise<void> {
  for (const statement of statements) {
    await sql.raw(statement).execute(db);
  }
}
